fn count_close(piece: String) -> Int {
  return len(split(piece, ")")) - 1
}

fn balanced_parens(s: String) -> Bool {
  var depth = 0
  var ok = true
  for p in enumerate(split(s, "(")) {
    if p.0 > 0 {
      depth = depth + 1
    }
    depth = depth - count_close(p.1)
    if depth < 0 {
      ok = false
    }
  }
  return ok and depth == 0
}

