type Shape =
  | Circle(radius: Float)
  | Rect(width: Float, height: Float)
  | Triangle(base: Float, height: Float)

fn area(s: Shape) -> Float {
  return match s {
    Circle(r) => 3.14159 * r * r,
    Rect(w, h) => w * h,
    Triangle(b, h) => b * h / 2.0,
  }
}

fn total_area(shapes: List[Shape]) -> Float {
  return sum_float(map(shapes, |s| area(s)))
}

