fn empty_stack() -> List[Int] {
  return []
}

fn is_op(t: String) -> Bool {
  return t == "+" or t == "-" or t == "*" or t == "/"
}

fn apply(op: String, a: Int, b: Int) -> Result[Int, String] {
  if op == "+" {
    return Ok(a + b)
  }
  if op == "-" {
    return Ok(a - b)
  }
  if op == "*" {
    return Ok(a * b)
  }
  if b == 0 {
    return Err("division by zero")
  }
  return Ok(a / b)
}

fn step(stack: List[Int], t: String) -> Result[List[Int], String] {
  if is_op(t) {
    let n = len(stack)
    if n < 2 {
      return Err("stack underflow")
    }
    let b = unwrap_or(last(stack), 0)
    let init = take(stack, n - 1)
    let a = unwrap_or(last(init), 0)
    let rest = take(stack, n - 2)
    let v = try apply(t, a, b)
    return Ok(append(rest, v))
  }
  return match parse_int(t) {
    Some(v) => Ok(append(stack, v)),
    None => Err("bad token: " + t),
  }
}

