fn strip_digits(s: String) -> String {
  return fold(range(0, 10), s, |acc, d| join(split(acc, to_string(d)), ""))
}

fn digits_only(s: String) -> Bool {
  return str_len(s) > 0 and strip_digits(s) == ""
}

fn parse_token(tok: String) -> Option[Int] {
  let parts = split(tok, "-")
  if len(parts) == 1 {
    if digits_only(tok) {
      return parse_int(tok)
    }
    return None
  }
  if len(parts) == 2 {
    let head = unwrap_or(first(parts), "x")
    let tail = unwrap_or(last(parts), "")
    if head == "" and digits_only(tail) {
      return parse_int(tok)
    }
  }
  return None
}

fn token_value(tok: String) -> Result[Int, String] {
  return match parse_token(tok) {
    Some(x) => Ok(x),
    None => Err("bad token: " + tok),
  }
}

fn apply(op: String, a: Int, b: Int) -> Result[Int, String] {
  if op == "+" {
    return Ok(a + b)
  }
  if op == "-" {
    return Ok(a - b)
  }
  if op == "*" {
    return Ok(a * b)
  }
  if b == 0 {
    return Err("division by zero")
  }
  return Ok(a / b)
}

fn rpn(tokens: List[String]) -> Result[Int, String] {
  var stack = []
  for tok in tokens {
    if tok == "+" or tok == "-" or tok == "*" or tok == "/" {
      let n = len(stack)
      if n < 2 {
        return Err("stack underflow")
      }
      let b = unwrap_or(last(stack), 0)
      let rest = take(stack, n - 1)
      let a = unwrap_or(last(rest), 0)
      let v = try apply(tok, a, b)
      stack = append(take(rest, n - 2), v)
    } else {
      let v = try token_value(tok)
      stack = append(stack, v)
    }
  }
  if len(stack) != 1 {
    return Err("expected one value")
  }
  let answer = unwrap_or(first(stack), 0)
  return Ok(answer)
}

