export function is_prime(n: number): boolean {
  if (!Number.isFinite(n) || !Number.isInteger(n)) {
    return false;
  }
  if (n < 2) {
    return false;
  }
  if (n < 4) {
    return true;
  }
  if (n % 2 === 0 || n % 3 === 0) {
    return false;
  }
  const limit = Math.floor(Math.sqrt(n));
  for (let i = 5; i <= limit; i += 6) {
    if (n % i === 0 || n % (i + 2) === 0) {
      return false;
    }
  }
  return true;
}

