export function digit_sum(n: number): number {
  if (!Number.isFinite(n)) {
    throw new RangeError("digit_sum: n must be a finite number");
  }
  const value = Math.trunc(Math.abs(n));
  // BigInt conversion gives the exact decimal expansion of the integer,
  // avoiding exponential notation (e.g. 1e21) and floating-point division errors.
  const digits = BigInt(value).toString();
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    sum += digits.charCodeAt(i) - 48;
  }
  return sum;
}

