function decimalDigitsOf(n: number): string {
  if (!Number.isFinite(n)) {
    throw new RangeError("digit_sum: n must be a finite number");
  }
  const whole = Math.trunc(Math.abs(n));
  // BigInt gives an exact decimal representation even for very large
  // integers, where String(n) would switch to exponential notation.
  return BigInt(whole).toString(10);
}

export function digit_sum(n: number): number {
  const digits = decimalDigitsOf(n);
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    sum += digits.charCodeAt(i) - 48;
  }
  return sum;
}

