export function digit_sum(n: number): number {
  if (!Number.isFinite(n) || n < 0) {
    throw new RangeError("digit_sum expects a finite non-negative number");
  }

  const value = Math.trunc(n);

  if (Number.isSafeInteger(value)) {
    let remaining = value;
    let sum = 0;
    while (remaining > 0) {
      sum += remaining % 10;
      remaining = Math.floor(remaining / 10);
    }
    return sum;
  }

  // Large integers: use BigInt to get the exact decimal representation
  // (avoids exponential notation from Number.prototype.toString).
  const digits = BigInt(value).toString();
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    sum += digits.charCodeAt(i) - 48;
  }
  return sum;
}

