export function repeat_string(s: string, n: number): string {
  if (!Number.isFinite(n) || n <= 0) {
    return "";
  }
  const count = Math.floor(n);
  let result = "";
  let base = s;
  let k = count;
  while (k > 0) {
    if (k & 1) {
      result += base;
    }
    k = Math.floor(k / 2);
    if (k > 0) {
      base += base;
    }
  }
  return result;
}

