function isSafe(v: number): boolean {
  return Number.isSafeInteger(v);
}

function bruteForce(xs: number[], target: number): number {
  let count = 0;
  const n = xs.length;
  for (let i = 0; i < n; i++) {
    const a = xs[i];
    for (let j = i + 1; j < n; j++) {
      if (a + xs[j] === target) count++;
    }
  }
  return count;
}

export function pairs_summing(xs: number[], target: number): number {
  let allSafe = isSafe(target);
  if (allSafe) {
    for (const x of xs) {
      if (!isSafe(x) || !isSafe(target - x)) {
        allSafe = false;
        break;
      }
    }
  }
  if (!allSafe) {
    return bruteForce(xs, target);
  }

  const seen = new Map<number, number>();
  let count = 0;
  for (const x of xs) {
    const need = target - x;
    const c = seen.get(need);
    if (c !== undefined) count += c;
    seen.set(x, (seen.get(x) ?? 0) + 1);
  }
  return count;
}

