export function collatz_steps(n: number): number {
  if (!Number.isInteger(n) || n < 1) {
    throw new RangeError("n must be an integer >= 1");
  }

  let steps = 0;
  let m = n;

  // Fast path using numbers while values remain safely representable.
  while (m !== 1) {
    if (m % 2 === 0) {
      m = m / 2;
    } else {
      const next = 3 * m + 1;
      if (next > Number.MAX_SAFE_INTEGER) {
        return steps + bigCollatzSteps(BigInt(m));
      }
      m = next;
    }
    steps++;
  }

  return steps;
}

function bigCollatzSteps(start: bigint): number {
  let steps = 0;
  let m = start;
  const one = 1n;
  const two = 2n;
  const three = 3n;
  while (m !== one) {
    if (m % two === 0n) {
      m = m / two;
    } else {
      m = three * m + one;
    }
    steps++;
  }
  return steps;
}

