  if (!Number.isInteger(n) || n < 1) {
    throw new RangeError("n must be an integer >= 1");
  }

  let steps = 0;
  let m = n;

  // Work in plain numbers while it is safe to do so.
  const SAFE_ODD_LIMIT = Math.floor((Number.MAX_SAFE_INTEGER - 1) / 3);
  while (m !== 1) {
    if (m % 2 === 0) {
      m = m / 2;
    } else {
      if (m > SAFE_ODD_LIMIT) {
        return steps + collatzStepsBig(BigInt(m));
      }
      m = 3 * m + 1;
    }
    steps++;
  }
  return steps;
}

function collatzStepsBig(start: bigint): number {
  let steps = 0;
  let m = start;
  while (m !== 1n) {
    if ((m & 1n) === 0n) {
      m >>= 1n;
    } else {
      m = 3n * m + 1n;
    }
    steps++;
  }
  return steps;
}

