  const result: number[] = [];
  if (!Number.isFinite(n) || n <= 0) {
    return result;
  }
  const count = Math.floor(n);
  let sum = 0;
  for (let i = 1; i <= count; i++) {
    sum += i;
    result.push(sum);
  }
  return result;
}

