export function count_char(s: string, c: string): number {
  if (c.length === 0) {
    return 0;
  }
  let count = 0;
  let index = s.indexOf(c);
  while (index !== -1) {
    count++;
    index = s.indexOf(c, index + c.length);
  }
  return count;
}

