export function count_char(s: string, c: string): number {
  if (c.length === 0) {
    return 0;
  }

  const cps = Array.from(c);
  if (cps.length === 1 && !isLoneSurrogate(c)) {
    // c is a single code point: compare against each code point of s.
    let count = 0;
    for (const ch of s) {
      if (ch === c) {
        count++;
      }
    }
    return count;
  }

  // Fallback: count non-overlapping occurrences of c as a substring.
  let count = 0;
  let idx = s.indexOf(c);
  while (idx !== -1) {
    count++;
    idx = s.indexOf(c, idx + c.length);
  }
  return count;
}

function isLoneSurrogate(c: string): boolean {
  if (c.length !== 1) {
    return false;
  }
  const code = c.charCodeAt(0);
  return code >= 0xd800 && code <= 0xdfff;
}

