type Item = { sku: string; qty: number; min: number };

export function restock(items: Item[]): string[] {
  const candidates: { sku: string; shortfall: number; index: number }[] = [];
  items.forEach((item, index) => {
    if (item.qty < item.min) {
      candidates.push({ sku: item.sku, shortfall: item.min - item.qty, index });
    }
  });
  candidates.sort((a, b) => {
    if (b.shortfall !== a.shortfall) return b.shortfall - a.shortfall;
    return a.index - b.index;
  });
  return candidates.map((c) => c.sku);
}

