const INTEGER_RE = /^-?[0-9]+$/;

function parseItem(item: string): [string, number] | null {
  const eqIndex = item.indexOf("=");
  if (eqIndex === -1) {
    return null;
  }
  if (item.indexOf("=", eqIndex + 1) !== -1) {
    return null;
  }
  const key = item.slice(0, eqIndex);
  const valueText = item.slice(eqIndex + 1);
  if (!INTEGER_RE.test(valueText)) {
    return null;
  }
  const parsed = Number(valueText);
  if (!Number.isFinite(parsed)) {
    return null;
  }
  const value = parsed === 0 ? 0 : parsed;
  return [key, value];
}

