  if (m.length === 0) {
    return [];
  }
  const rows = m.length;
  const cols = m[0].length;
  const result: number[][] = [];
  for (let c = 0; c < cols; c++) {
    const newRow: number[] = new Array<number>(rows);
    for (let r = 0; r < rows; r++) {
