export function run_lengths(s: string): ([string, number])[] {
  const result: ([string, number])[] = [];
  let current: string | null = null;
  let count = 0;

  for (const ch of s) {
    if (current === null) {
      current = ch;
      count = 1;
    } else if (ch === current) {
      count++;
    } else {
      result.push([current, count]);
      current = ch;
      count = 1;
    }
  }

  if (current !== null) {
    result.push([current, count]);
  }

  return result;
}

