  if (u.name === "") {
    problems.push("name is empty");
  }
  if (u.age < 0 || u.age > 150) {
    problems.push("age out of range");
  }
  if (!u.email.includes("@")) {
    problems.push("email must contain @");
  }
  return problems;
}

