fn triangular_number(k: Int) -> Int {
  if k % 2 == 0 {
    return k / 2 * (k + 1)
  }
  return k * (k / 2 + 1)
}

fn triangle_numbers(n: Int) -> List[Int]
  requires: n >= 0
{
  return map(range(0, n), |i| triangular_number(i + 1))
}

