type Shape =
  | Circle(radius: Float)
  | Rect(width: Float, height: Float)
  | Triangle(base: Float, height: Float)

fn shape_area(shape: Shape) -> Float {
  return match shape {
    Circle(radius) => 3.14159 * radius * radius,
    Rect(width, height) => width * height,
    Triangle(base, height) => base * height / 2.0,
  }
}

fn total_area(shapes: List[Shape]) -> Float {
  var total = 0.0
  for shape in shapes {
    total = total + shape_area(shape)
  }
  return total
}

