type Item {
  sku: String,
  qty: Int,
  min: Int,
}

fn shortfall_key(item: Item) -> (Int, Int, String) {
  # Split the difference into base-4 parts to avoid Int overflow.
  let low = item.min % 4 - item.qty % 4 + 8
  let high = item.min / 4 - item.qty / 4 + low / 4 - 2
  return (high, low % 4, item.sku)
}

fn restock(items: List[Item]) -> List[String] {
  return items
    |> filter(|item| item.qty < item.min)
    |> map(shortfall_key)
    |> sort_desc_by(|entry| entry.1)
    |> sort_desc_by(|entry| entry.0)
    |> map(|entry| entry.2)
}

