fn shortfall_key(item: Item) -> (Int, Int, String) {
  # Split the shortfall into two parts so the full difference cannot overflow.
  let high = item.min / 2 - item.qty / 2
  let low = item.min % 2 - item.qty % 2
  let carry = (low + 2) / 2 - 1
  return (high + carry, low - carry * 2, item.sku)
}

fn restock(items: List[Item]) -> List[String] {
  return items
    |> filter(|i| i.qty < i.min)
    |> map(shortfall_key)
    |> sort_desc_by(|entry| entry.1)
    |> sort_desc_by(|entry| entry.0)
    |> map(|entry| entry.2)
}

