type Item {
  sku: String,
  qty: Int,
  min: Int,
}

# Split the shortfall into a quotient and a low bit to avoid Int overflow.
fn shortfall_parts(item: Item) -> (Int, Int) {
  let min_half = item.min / 2
  let qty_half = item.qty / 2
  let min_rem = item.min - min_half * 2
  let qty_rem = item.qty - qty_half * 2
  let shifted = min_rem - qty_rem + 2
  let carry = shifted / 2 - 1
  return (min_half - qty_half + carry, shifted % 2)
}

fn restock(items: List[Item]) -> List[String] {
  return items
    |> filter(|item| item.qty < item.min)
    |> map(|item| (shortfall_parts(item), item.sku))
    |> sort_desc_by(|parts, sku| parts.1)
    |> sort_desc_by(|parts, sku| parts.0)
    |> map(|parts, sku| sku)
}

