fn rpn_parse(token: String) -> Result[Int, String] {
  let bad_token = "bad token: " + token
  var digits = filter(split(token, ""), |ch| ch != "")
  if first(digits) == Some("-") {
    digits = drop(digits, 1)
  }
  if len(digits) == 0 {
