  email: String,
}

fn validate_user(u: User) -> List[String] {
  let checks = [
    (u.name == "", "name is empty"),
    (u.age < 0 or u.age > 150, "age out of range"),
    (len(split(u.email, "@")) == 1, "email must contain @"),
  ]
  let failed = filter(checks, |check| check.0)
  return map(failed, |check| check.1)
}

