export function fib(n: number): number {
  // F(1477) is the first Fibonacci number too large for a finite number.
  if (n >= 1477) return Infinity;

  let current = 0n;
  let next = 1n;

  for (let i = 0; i < n; i++) {
    const sum = current + next;
    current = next;
    next = sum;
  }

  return Number(current);
}

