export function digit_sum(n: number): number {
  if (!Number.isFinite(n) || n < 0) {
    throw new RangeError("n must be a finite nonnegative number");
  }

  const decimal = Number.isInteger(n) ? BigInt(n).toString() : n.toString();
  let sum = 0;

  for (let i = 0; i < decimal.length; i++) {
    const code = decimal.charCodeAt(i);
    if (code === 101) break; // Exponent notation only shifts the decimal point.
    if (code >= 48 && code <= 57) {
      sum += code - 48;
    }
  }

  return sum;
}

