  if (xs.length === 0) {
    return 0.0;
  }

  let sum = 0;
  for (const x of xs) {
    sum += x;
  }

  if (Number.isFinite(sum)) {
    return sum / xs.length;
  }

  // Scale before summing if the sum of finite values overflowed.
  let scaledSum = 0;
  for (const x of xs) {
    scaledSum += x / xs.length;
  }

  return scaledSum;
}

