export function pairs_summing(xs: number[], target: number): number {
  const sorted = [...xs].sort((a, b) => a - b);
  let count = 0;

  function boundary(i: number, includeEqual: boolean): number {
    let lo = i + 1;
    let hi = sorted.length;

    while (lo < hi) {
      const mid = lo + Math.floor((hi - lo) / 2);
      const sum = sorted[i] + sorted[mid];

      if (sum < target || (includeEqual && sum === target)) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }

    return lo;
  }

  for (let i = 0; i + 1 < sorted.length; i++) {
    count += boundary(i, true) - boundary(i, false);
  }

  return count;
}

