export function pairs_summing(xs: number[], target: number): number {
  if (!Number.isSafeInteger(target) || !xs.every(Number.isSafeInteger)) {
    // With rounded sums, subtracting from the target can miss valid pairs.
    let count = 0;
    for (let j = 1; j < xs.length; j++) {
      for (let i = 0; i < j; i++) {
        if (xs[i] + xs[j] === target) {
          count++;
        }
      }
    }
    return count;
  }

  const seen = new Map<number, number>();
  let count = 0;

  for (const x of xs) {
    count += seen.get(target - x) ?? 0;
    seen.set(x, (seen.get(x) ?? 0) + 1);
  }

  return count;
}

