export function balanced_parens(s: string): boolean {
  let depth = 0;

  for (const char of s) {
    if (char === "(") {
      depth++;
    } else if (char === ")") {
      if (depth === 0) return false;
      depth--;
    }
  }

  return depth === 0;
}

