export function pairs_summing(xs: number[], target: number): number {
  if (xs.length < 2 || Number.isNaN(target)) {
    return 0;
  }

  const sorted = xs.slice().sort((a, b) => a - b);
  let firstAtLeast = sorted.length;
  let firstGreater = sorted.length;
  let count = 0n;

  for (let i = 0; i < sorted.length - 1; i++) {
    const start = i + 1;
    const x = sorted[i];

    // As x increases, both boundaries move only to the left.
    // Compare sums directly so rounding does not affect a complement lookup.
    while (firstAtLeast > start && x + sorted[firstAtLeast - 1] >= target) {
      firstAtLeast--;
    }
    while (firstGreater > start && x + sorted[firstGreater - 1] > target) {
      firstGreater--;
    }

    const matches = Math.max(firstGreater, start) - Math.max(firstAtLeast, start);
    if (matches > 0) {
      count += BigInt(matches);
    }
  }

  return Number(count);
}

