export function collatz_steps(n: number): number {
  if (!Number.isInteger(n) || n < 1) {
    throw new RangeError("n must be a positive integer");
  }

  let current = BigInt(n);
  let steps = 0;

  while (current !== 1n) {
    current = current % 2n === 0n ? current / 2n : 3n * current + 1n;
    steps++;
  }

  return steps;
}

