type Op = { kind: "Deposit"; amount: number } | { kind: "Withdraw"; amount: number };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function apply_ops(balance: number, ops: Op[]): Result<number> {
  let step = 0;

  for (const op of ops) {
    step += 1;

    if (op.kind === "Deposit") {
      balance += op.amount;
    } else {
      if (op.amount > balance) {
        return { ok: false, error: `insufficient funds at step ${step}` };
      }
      balance -= op.amount;
    }
  }

  return { ok: true, value: balance };
}

